/* Isolated lesson data only: no session or record writes. */
(() => {
  'use strict';
  const game=document.body.dataset.soloGame,code=game==='code',C=SoloCore,L=LearningCore;
  if(!['code','chain'].includes(game))return;
  const name=code?'코드 브레이커':'숫자 연쇄',lessons=code?L.codeLessons:L.chainLessons,colors=['빨강','파랑','초록','노랑'];
  const dialog=document.createElement('dialog');dialog.id='card-picture-practice';dialog.setAttribute('aria-labelledby','picture-practice-title');document.body.appendChild(dialog);
  let step=0,selected=null,solved=false,message='',guess='',chain=[],offer=[],redrawn=false,comparison=null;
  const tile=id=>{const c=C.card(id);return `<span class="chain-card color-${c.color}"><b>${c.number}</b><small>${colors[c.color]}</small></span>`;};
  const digits=value=>`<div class="practice-digits">${[...value].map((n,i)=>`<span><small>${i+1}번째</small><b>${n}</b></span>`).join('')}</div>`;
  function reset(){const p=lessons[step];selected=null;solved=false;message='';comparison=null;guess=p.guess||'';chain=p.chain?.slice()||[];offer=p.offer?.slice()||[];redrawn=false;render();}
  function codeView(){const p=lessons[step];return `<p>연습에서는 정답을 공개해 두 줄을 비교해요. 본게임은 암호를 숨기고 개수만 알려줍니다.</p><h4>연습 정답</h4>${digits(p.secret)}${p.guess?`<h4>비교할 입력</h4>${digits(guess)}<button type="button" class="primary" data-check>칸별 단서 확인하기</button>`:`<form data-practice-form><label for="practice-code-input">0~7 중 서로 다른 숫자 네 자리</label><input id="practice-code-input" name="guess" inputmode="numeric" maxlength="4" autocomplete="off" value="${guess}" placeholder="예: 2067"><button class="primary" type="submit">단서 확인</button></form><p>횟수 제한 없이 바꿔보세요. 정답은 위의 네 자리예요.</p>`}${comparison?`<div class="practice-code-results">${comparison.map(c=>`<div class="clue-${c.kind}"><b>${c.digit}</b><span>${c.kind==='exact'?`↓ ${c.index+1}번째 자리 일치`:c.kind==='misplaced'?`↔ 정답의 ${c.target+1}번째 자리`:'× 정답에 없는 숫자'}</span></div>`).join('')}</div><p class="practice-clue-totals">위치 일치 ${comparison.filter(c=>c.kind==='exact').length}개 · 숫자만 포함 ${comparison.filter(c=>c.kind==='misplaced').length}개</p>`:''}`;}
  function chainView(){const p=lessons[step],blocked=!offer.some(id=>['left','right'].some(side=>L.chainConnection(id,side==='left'?chain[0]:chain.at(-1),C.card).ok));return `<p>같은 색 <b>또는</b> 숫자 차이 1이면 연결해요. 같은 숫자만으로는 연결되지 않아요.</p><div class="chain-ends"><section><h4>왼쪽 끝</h4>${tile(chain[0])}</section><span class="practice-chain-arrow" aria-hidden="true">← →</span><section><h4>오른쪽 끝</h4>${tile(chain.at(-1))}</section></div><h4>카드를 고르고 놓을 쪽을 누르세요</h4><div class="chain-offer">${offer.map((id,i)=>`<button type="button" data-practice-card="${i}" aria-pressed="${selected===i}" aria-label="연습 ${colors[C.card(id).color]} ${C.card(id).number} 선택" ${solved?'disabled':''}>${tile(id)}<small>${selected===i?'선택됨':'눌러보기'}</small></button>`).join('')}</div><div class="chain-placement"><button type="button" data-practice-side="left" ${selected===null||solved?'disabled':''}>← 왼쪽에 놓기</button><button type="button" data-practice-side="right" ${selected===null||solved?'disabled':''}>오른쪽에 놓기 →</button></div>${step===3?`<button type="button" data-practice-redraw ${!blocked||redrawn||solved?'disabled':''}>공개 카드 재추첨</button><p>${blocked?'양 끝에 놓을 수 있는 카드가 없어요. 재추첨을 눌러보세요.':'연결 가능한 카드가 있으면 재추첨할 수 없어요.'} 본게임에서는 최대 2회예요.</p>`:''}<p class="note">배치 +2점 · 숫자 차이 1이면 추가 +1점 · 본게임은 12회 배치</p>`;}
  function render(){dialog.innerHTML=`<div class="dialog-head"><span>그림으로 배우기 · ${step+1}/${lessons.length}</span><button type="button" data-practice-close aria-label="${name} 연습 닫기">닫기</button></div><h2 id="picture-practice-title" tabindex="-1">${name} · 그림 연습</h2><p class="practice-note">시간·횟수 제한 없이 연습해요. 실제 게임의 진행과 완료 기록은 그대로 유지됩니다.</p><h3>${lessons[step].title}</h3>${code?codeView():chainView()}<p class="light-practice-status" role="status" aria-live="polite">${message||'틀려도 괜찮아요. 그림을 보며 직접 눌러보세요.'}</p><div class="actions practice-actions"><button type="button" data-practice-reset>이 연습 다시 하기</button>${solved&&step<lessons.length-1?'<button type="button" class="primary" data-practice-next>다음 연습 →</button>':''}</div><button type="button" class="practice-entry light-return" data-practice-close>${solved&&step===lessons.length-1?'연습 완료 · 실제 게임으로 돌아가기':'실제 게임으로 돌아가기'}</button>`;}
  function check(value){if(!/^[0-7]{4}$/.test(value)||new Set(value).size!==4){message='0~7 중 서로 다른 숫자 네 자리를 입력해주세요. 횟수는 줄지 않아요.';render();return;}guess=value;comparison=L.codeComparison(lessons[step].secret,guess);solved=step<2||comparison.every(c=>c.kind==='exact');message=solved?'잘했어요! 단서를 확인했어요. 연습은 실제 기록에 포함되지 않아요.':'단서의 화살표를 보고 자리를 바꿔보세요. 몇 번이든 다시 입력할 수 있어요.';render();if(step===2&&!solved)dialog.querySelector('input').focus();}
  dialog.addEventListener('submit',e=>{e.preventDefault();check(new FormData(e.target).get('guess').trim());});
  dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-practice-close'))dialog.close();else if(b.hasAttribute('data-practice-reset'))reset();else if(b.hasAttribute('data-practice-next')){step++;reset();dialog.querySelector('h2').focus();}else if(b.hasAttribute('data-check'))check(guess);else if(b.hasAttribute('data-practice-card')){selected=+b.dataset.practiceCard;message='선택한 카드를 어느 끝에 연결할지 골라보세요.';render();}else if(b.hasAttribute('data-practice-redraw')){offer=lessons[step].replacement.slice();selected=null;redrawn=true;message='막힌 카드 3장을 바꿨어요. 배치 횟수는 쓰지 않아요. 새 카드로 연결해보세요.';render();}else if(b.hasAttribute('data-practice-side')){const side=b.dataset.practiceSide,id=offer[selected],end=side==='left'?chain[0]:chain.at(-1),r=L.chainConnection(id,end,C.card);if(!r.ok)message='색이 다르고 숫자 차이도 1이 아니에요. 다른 카드나 반대쪽 끝을 골라보세요.';else{side==='left'?chain.unshift(id):chain.push(id);solved=true;message=`${r.same?'같은 색으로 연결':'숫자 차이 1로 연결'}! 배치 +2점${r.near?' + 숫자 차이 1 보너스 +1점':''} = +${r.points}점. 실제 기록에는 포함되지 않아요.`;}render();}});
  function open(){step=0;reset();dialog.showModal();dialog.querySelector('h2').focus();}
  const button=document.createElement('button');button.type='button';button.className='practice-entry';button.textContent='시간제한 없는 그림 연습';button.addEventListener('click',open);document.querySelector('.solo-tools').prepend(button);
  if(new URLSearchParams(location.search).get('practice')==='1')open();
})();
